import React from 'react';

import { InternalSliceData } from '../types/internal/pie-chart.js';
import { InnerHandler } from '../types/pie-chart.config.js';

const initialValue = {
  innerElement: () => null,
  originalData: [],
};

export const InnerElementContext = React.createContext<{
  innerElement: InnerHandler | React.ReactNode;
  originalData: InternalSliceData[];
}>(initialValue);

export const useChartInnerElement = () => React.useContext(InnerElementContext);

InnerElementContext['displayName'] = 'InnerElementContext';
